// ============ 暗巷论坛普通帖子 (原样保留你所有的精彩正文) ============

const DEFAULT_POSTS = [
    { id:'p1', title:'有人记得19年三院的事吗？', author:'匿名_4f3a', board:'求助解惑', views: 1286, image:'images/feature-darkred.jpg', content:'今天路过老第三医院，突然心口发闷，脑子里闪了点白影子，但怎么都想不起来发生过啥。\n\n我不是在说恐怖故事，我是在说那种明明发生过却又完全记不起来的感觉。那间医院门口的老树，下午还正常，晚上却像被什么东西看着。走近时，路灯会忽明忽暗，像有人在灯泡后面用手捂住。\n\n我当时站在急诊科的玻璃门前，脚下的地砖像在轻微震动，像有人在下面穿过走廊。几秒钟后，脑中冒出一句话："别回头。" 但我根本没有转身。\n\n有没有人也有这种感觉？那地方晚上路灯总是忽明忽暗。', timestamp:'2026-01-15 23:41', comments:[ { user:'匿名_9b2c', text:'老医院那类地方，晚上看病的人少，反而更像场所本身在盯人。', time:'2026-01-15 23:55', floor:2 }, { user:'匿名_7d1e', text:'19年那会儿我在三院实习过，晚上值班室确实有段时间老有人反应走廊尽头那间病房门自己开合，后来院长亲自去处理过。', time:'2026-01-16 00:12', floor:3 }, { user:'匿名_4f3a', text:'楼上是真的在那边实习吗…我想多问两句，但是又不太敢深聊，怕想起更多。', time:'2026-01-16 00:31', isOP:true, floor:4 }, { user:'匿名_c2a9', text:'你们说的是第三人民医院老院区吧？那边以前是防疫站的旧址，老一辈都说底下埋过东西。', time:'2026-01-16 08:05', floor:5 } ] },
    { id:'p2', title:'夜班出租车司机的奇怪经历', author:'匿名_12ab', board:'灵异见闻', views: 2431, image:'images/post-taxi.jpg', content:'昨晚拉了个客人，从老城区到东郊，一路上一句话没说。车里很安静，连收音机都没开。等我在路口靠边停下时，后座那个人突然说了一句："别回头，看前面。"\n\n我一听就不对劲，心里一紧，手指却不由自主地停在了方向盘上。下车的时候我回头看后座，人不见了，但车门根本没开过。钱倒是给了，是真钞。还夹在副驾驶的杯架里，面额没错。\n\n我开回公司时，车里的后排座位竟然有一条白色的长头发，像刚刚被人放上去的。我想报警，又想起自己刚才还在路口打过转。', timestamp:'2026-01-14 02:15', comments:[ { user:'匿名_5f6g', text:'后排白发是老城区那些夜里被放错路的人的遗留，不要再跑那一带了。', time:'2026-01-14 09:30', floor:2 }, { user:'匿名_8e2a', text:'老司机圈里管这叫"顺风客"，收了钱就别回头看，回头容易把东西带回来。', time:'2026-01-14 10:44', floor:3 }, { user:'匿名_12ab', text:'我当时真没敢回头，就盯着后视镜确认人不见了才松的手刹。那撮头发我连碰都不敢碰，隔天就烧了。', time:'2026-01-14 11:02', isOP:true, floor:4 }, { user:'匿名_b0f6', text:'同行，我上个月也遇到一回，在东郊那条断头路上。后来我把那段路的单子全推了。', time:'2026-01-15 02:18', floor:5 } ] },
    { id:'p3', title:'谁在我床底下放了一面镜子？', author:'匿名_9e7c', board:'巷中秘闻', views: 3520, image:'images/post-mirror-v2.jpg', content:'前天晚上关灯后，听到床底下有东西在挠木板。不是敲门，不像爪子，像有人在里面用指甲慢慢摸那块木板。拿手电一照，发现床板内侧贴着一面巴掌大的圆镜，镜面上蒙了一层黄符。\n\n我发誓那不是我的东西。\n\n更诡异的是，镜里没有我自己的倒影，只有一块窗户的形状，像有人在镜子后面透光。第二天我想把它拿出来，发现木板缝里还留着一撮很细很短的头发，颜色像烂掉的金箔。\n\n我现在睡觉都把床腿塞进了鞋盒里。', timestamp:'2026-01-12 01:04', comments:[ { user:'匿名_3a1b', text:'快扔了！用红布包着埋土里，不要放家里。', time:'2026-01-12 02:20', floor:2 }, { user:'匿名_6c7d', text:'床板内侧贴镜是"照床"的讲究，一般是镇东西用的，但这面镜子怕是反过来被镇了。', time:'2026-01-12 09:15', floor:3 }, { user:'匿名_9e7c', text:'我现在怕的是那撮头发，金箔颜色的…我家没人染过那个颜色。', time:'2026-01-12 23:40', isOP:true, floor:4 }, { user:'匿名_e4b8', text:'金箔色头发…我老家那边老人说那是"烧过的东西"的记号，你最好把镜子原样放回去，别乱动。', time:'2026-01-13 07:22', floor:5 } ] },
    { id:'p4', title:'小时候村里的"过阴"仪式', author:'匿名_7b2a', board:'民俗考据', views: 1894, image:'images/ritual-ink.jpg', content:'奶奶说她年轻时村里有个神婆能"过阴"，整个人躺在地上，头前面点一盏油灯。灯不灭，人就还在；灯一灭，就回不来了。\n\n她当年在场，整晚都不敢看那盏灯。直到半夜里，神婆突然开始念咒，声音像在地底下发出来。只听见她说："不要让他看见你。" 然后整个屋子都冰得发疼。\n\n有一次神婆下去之后，灯突然自己灭了，然后她又自己爬起来了，但再也不说话，只是哭。后来去找她问，神婆只说一句："她回来时，脚底下不是泥。"', timestamp:'2026-01-10 17:33', comments:[ { user:'匿名_2f9d', text:'"过阴"在闽南那边叫"观落阴"，规矩更多，进门前脚不能沾地气。', time:'2026-01-10 19:20', floor:2 }, { user:'匿名_5b4c', text:'灯灭人还在，那就不是回来了。她哭，多半是因为看到底下有不该看的东西。', time:'2026-01-11 03:02', floor:3 }, { user:'匿名_7b2a', text:'我一直不敢细问奶奶那晚到底发生了什么，她从那以后就再也没给人过过阴。', time:'2026-01-11 12:33', isOP:true, floor:4 } ] },
    { id:'p5', title:'找到一本奇怪的手抄本', author:'匿名_1f3e', board:'巷中秘闻', views: 2755, image:'images/post-notebook.jpg', content:'回老家整理旧屋，在奶奶的陪嫁箱子底层找到一本黄皮线装本，上面写的全是"规矩"：\n1. 晚上听见有人喊你全名，不要应，不要回头。\n2. 在巷子里遇到穿红鞋的人，闭眼往后退七步。\n3. 如果醒来发现自己在镜子前，记得先遮住镜面再开灯。\n\n我翻开后面的页，里面夹着一张黑白照片，照片里有一个人站在门口，衣服是我祖辈的老款式，可他头顶却没有影子。我盯着照片看了很久，直到我发现整本手抄本的纸边都被人用针扎过。\n\n我想起奶奶以前总在夜里把门闩两遍，但从来不关窗。', timestamp:'2026-01-08 22:47', comments:[ { user:'匿名_a9b8', text:'这是民间的"避煞"口诀，真正危险的是它背后的用法。', time:'2026-01-09 09:10', floor:2 }, { user:'匿名_3d7f', text:'纸边被针扎过是"记数"，一张照片一个数。你数数针眼有几排，大概就是"它"来过几次。', time:'2026-01-09 14:26', floor:3 }, { user:'匿名_1f3e', text:'我数了，三排，每排九个针眼。看完手都是凉的。', time:'2026-01-09 22:47', isOP:true, floor:4 } ] },
    { id:'p6', title:'【卷一】临川高中异常档案解密', author:'匿名_7d2e', board:'灵异见闻', content:'经整理，关于明德楼的那次深夜广播事件，调查记录指出广播内容带有强烈的认知污染。如果你听到有人敲门并要求你遵守规则，请务必保持冷静。\n\n以下是整理的守则摘录：\n1. 安静。\n2. 主动帮助同学。\n3. 尊敬师长。\n4. 垃圾分类。\n5. 不要投喂流浪动物，不要看它们的眼睛。\n6. 准时上课。\n7. 专注自己的功课。\n8. 熄灯后宿舍门是封死的，无论谁来敲都不要开。\n9. 找穿蓝色制服的工作人员。\n10. 相信这所学校。\n\n而真正让我不安的是，档案最后一页被人用红墨水加了一行小字："你们不需要知道它是谁，只需要知道它离你越来越近。"\n\n有人甚至说，广播里偶尔会夹杂一段低声，像是"所有人都要回到自己的房间，别在走廊里站着。"\n\n校方声明只说过三件事：广播声来自校内广播系统、所有记录均已做清洗、并没有任何人失踪。可问题是，明德楼四楼的走廊上，至今仍有人把棉拖鞋摆成整齐的一排，像在等什么人从门里走出来。\n\n我们后来又查到一份没有入档的手写副本，里面写着："所有在校学生都需要记住：当你听见广播时，不要抬头，别回头，别去看教室窗外。若你看见蓝色制服的人，立刻把自己的名字念给自己听，直到那个名字变成你的。"', timestamp:'2026-01-22 09:12', comments:[ { user:'匿名_6h3f', text:'总觉得这十大条规则背后藏着更加可怕的东西。', time:'2026-01-22 09:30' } ] },
    { id:'p7', title:'曝光！老城区地下停车场的手印', author:'匿名_3f1e', board:'巷中秘闻', views: 4078, image:'images/post-parking-v2.jpg', content:'老城区地下车库三层的墙壁上发现了大量不属于任何人类的手掌印记。这些印记大小不一，排列的间距完全不规则，但最诡异的是，所有的印记都指向了停车场深处的废弃电梯井。\n\n附近的老居民说，那栋楼之前因为发生恶性事故被封过。有人甚至说，那些印记不是被留下的，而是被按上去的，像谁在墙上用手指反复确认一件事情。\n\n想知道详情的人可以私下交流，禁止公开谈论。除了我以外，附近三家店的监控都在同一时刻失灵，连门口的红灯也忽然熄灭了一分钟。\n\n后来我才知道，电梯井里根本没有井底，只有一条黑色的通道。\n\n那天我在车库门口站了太久，才发现停车场边缘的墙面，所有的裂缝都朝着同一个方向，像有人在某个地方等你快步走过去，等你听见脚步声后，便把你一并推入那条无底的黑色通道。', timestamp:'2026-01-21 22:01', comments:[ { user:'匿名_8d7b', text:'我在那个停车场遇到过怪事...永远感觉背后有人跟着，甚至连同伴都没看见。', time:'2026-01-21 23:11', floor:2 }, { user:'匿名_0c4e', text:'监控同时失灵这个细节太对了，那边车库的信号本来就差，但连门口红灯都灭那一分钟说明不是信号问题。', time:'2026-01-22 07:45', floor:3 }, { user:'匿名_3f1e', text:'我现在路过那个车库都绕道，电梯井那扇铁门后来被焊死了，但我知道那不是物业焊的。', time:'2026-01-22 08:19', isOP:true, floor:4 } ] },
    { id:'p8', title:'我买到了一面能看到自己死亡方式的古董镜子', author:'匿名_7b2a', board:'巷中秘闻', views: 3128, image:'images/post-mirror-v2.jpg', content:'上周在老城区旧货市场淘到一面巴掌大的铜镜，卖货的老头说这镜子"有点年头了，放在家里镇宅不错"。我花了八十块买回来，当晚放在梳妆台上。\n\n半夜起床上厕所，路过镜子时瞥了一眼——镜子里映出的不是我，而是一个躺在病床上的老人，身上插满了管子，心电图正在变成一条直线。\n\n我以为自己睡迷糊了，揉了揉眼睛再去看，镜子里恢复了正常，是我的脸。但那种被"剧透死亡"的感觉让我一整晚没睡着。\n\n第二天白天，镜子里一切正常。第二天晚上，我又看了一眼——这次是一个浑身湿透的年轻人，躺在河滩上，脸被水泡得发白。我认得出那张脸。那是我的脸。\n\n第三天晚上，我没敢再看那面镜子。但我感觉那面镜子在看我。我用红布把它包了起来，塞进了衣柜最底层。第四天晚上，我在睡梦中听见衣柜里有东西在轻轻磕碰木板的声响——规律、沉闷、一下接一下。\n\n我把镜子拿出来，红布已经被扯开了一个角。我鼓起勇气看过去——镜子里是我自己，但身后站着一个穿寿衣的老太太，手里拿着一根麻绳。她冲我笑了一下，然后指了指我的脖子。\n\n今天我把镜子砸了。玻璃碎了一地，但碎片里每一片都在映出不同的"我"——有的在车祸中、有的躺在手术台上、有的在陌生的铁轨旁。我蹲在地上看了很久，直到发现自己拿锤子的手正在不受控制地发抖。\n\n我感觉它还没走。今晚我打算把碎片装进铁盒里，埋到小区花园的老槐树底下。有懂行的朋友说这样管用，但我不确定——因为我在埋它的时候，总感觉背后有脚步声，回头却什么也没有。', timestamp:'2026-01-18 23:41', comments:[ { user:'匿名_3a1b', text:'这种镜子我见过。旧货市场里偶尔会流出这种东西，来源一般是拆迁老宅。如果你已经砸了，建议把碎片单独用黑布包好，别用手直接碰。另外，埋的时候最好面朝西，别回头，憋着气把土填完。如果已经埋了，今晚注意听窗外有没有人喊你的名字。', time:'2026-01-19 00:12', floor:2 }, { user:'匿名_9b2c', text:'楼主你确定你看到的是"死亡方式"？我听说那种镜子其实是用来困住"死灵"的——镜子里的影像不是你未来的样子，而是镜子本身曾经见过的东西。你要是没被困住，就说明它还盯上你了。', time:'2026-01-19 01:04', floor:3 }, { user:'匿名_7b2a', text:'@匿名_3a1b 我已经埋了，你说面朝西，我没有看反吧？埋完回来之后感觉后背一直很凉。还有，刚刚我路过小区门口的监控，发现监控画面里我身后有一个人形白影——但当时明明只有我一个人。今天早上我路过埋镜子的地方，树根旁边的土翻开了，铁盒露了一半出来。我把它又埋深了一点。', time:'2026-01-19 08:30', isOP:true, floor:4 }, { user:'匿名_3a1b', text:'楼主你埋镜子的位置不对——你说了“总感觉背后有脚步声，回头却什么也没有”。埋镇物最忌回头，你回头了，就相当于把门又开了一次。今晚注意听窗外有没有人喊你名字，喊了千万别应。', time:'2026-01-19 09:00', floor:5 }, { user:'匿名_9b2c', text:'你砸镜子的碎片里“每一片都在映出不同的你”——这不是死亡方式，是那面镜子曾经“照过”的别人的结局，都攒在镜子里了。你砸了它，那些“我”就都放出来了。楼主你现在照镜子，镜子里还是你的脸吗？', time:'2026-01-19 10:20', floor:6 }, { user:'匿名_5f6g', text:'我也遇到过类似的镜子，在老城区旧货市场，摊主说“镇宅”。我买回来第二天早上，镜面上全是水雾，擦都擦不掉，水雾里好像有个人脸。我当天就把它退了。现在想想，退得对。楼主你那个铁盒，别埋老槐树底下了，埋深点，最好浇层水泥。', time:'2026-01-19 12:40', floor:7 }, { user:'匿名_1f3e', text:'我大半夜看到“它还没走”这句已经不敢去上厕所了。楼主你要是有条件，今晚去朋友家睡，别一个人待在家里。镜子这种东西，砸了不算完，它认的是“看过它的人”。', time:'2026-01-19 23:10', floor:8 }, { user:'匿名_8d7b', text:'楼主，你这两天没更新了，还在吗？你要是看到了这条，回个话。那面镜子要是真的“换了容器”——比如你家里还有别的镜子——你就把家里所有能反光的东西都用布盖上，一片别留。', time:'2026-01-21 09:30', floor:9 } ] },

    { id:'p9', title:'老城区中南大厦的楼梯，我走了一整夜没走到头', author:'匿名_12ab', board:'灵异见闻', views: 2986, image:'images/feature-purple.jpg', content:'先说结论：那座楼有13层，但它的楼梯间好像会吃人。那天晚上雨停了没多久，整条街都是湿漉漉的，路灯把水洼照成一片片碎银。我站在那栋楼门口，抬头数了数窗户，心里直发毛。\n\n上周五晚上，我跟朋友打赌能不能在废弃的"中南大厦"待一整晚。那栋楼十年前因为事故被封了，据说当时电梯失控从顶楼掉到底层，后来一直没人修。那天晚上12点整，我一个人从正门进去。\n\n一楼大厅很空旷，地上铺满了碎玻璃和旧报纸，墙上的消防疏散图上写着"本楼共13层"。我走到楼梯间开始往上走。\n\n1层、2层、3层——一切正常。7层、8层、9层——楼道里很黑，我开了手机手电筒。我走到11层时，发现楼梯间的墙上用红色油漆写了一行字："别回头，也别数楼层。"\n\n我心想这可能是哪个探险者留下的恶作剧，没当回事继续往上走。\n\n但我很快就发现了问题——按照楼层的标牌，我早该走到13层了。但我面前的楼梯还在往上延伸，没有尽头的铁灰色台阶在手机灯光下一级一级地往上爬。我看了眼手机的时间：00:47。\n\n我决定往下走。往下走的时候，我数着楼层——13、12、11、10、9、8、7、6、5、4、3、2——然后下一层应该是1层。但门推开之后，我看到了一个非常熟悉的场景：11层的楼道标牌。\n\n我还在11层。\n\n我又往下走了一次，这次我走得很快，几乎是跑下楼。又一次回到11层。\n\n第三次我换了个方法——我试着用手机拍下楼梯间照片，看能不能拍到什么异常。照片里没有多出任何东西，但所有照片的右下角都有一个模糊的、像人蹲在地上的影子。我用手机放大看的时候，那个影子好像动了一下。\n\n我决定不再尝试了。我推开了11层的防火门，走进了楼道。\n\n在楼道尽头，有一扇没有编号的门。我推开那扇门，是一条完全陌生的走廊——墙壁是白色的，地板是新的，头顶的日光灯管嗡嗡地响。走廊尽头有一张桌子，桌子上放着一杯还冒着热气的茶。\n\n我转身跑回楼梯间，然后一路往下冲。这次我没数楼层，也没看标牌，只管往下跑。大约跑了十几层之后，我推开了一扇门——是一楼大厅。\n\n我冲出了大楼，看了一眼手机：凌晨4:47。我在那栋楼里待了将近五个小时。\n\n后来我去查了那栋楼的资料。那个建筑的标准层高是3.2米，13层楼加起来应该不到42米，而我那天晚上在楼梯间里走了至少300多级台阶。还有一个更让我不安的细节——那栋楼里的所有楼层标牌，在竣工图上写的是"本楼共12层"，没有第13层。', timestamp:'2026-01-20 02:15', comments:[ { user:'匿名_5f6g', text:'中南大厦的事我听说过。那个电梯事故里死的人，据说就是被卡在13楼和14楼之间——但那栋楼根本没有14楼。老城区的人有句说法："不存在的楼层，是最真实的东西。"', time:'2026-01-20 09:30', floor:2 }, { user:'匿名_9e7c', text:'楼主你说拍了照片？能不能发出来看看？右下角的影子……我突然想起之前有人在旧纸厂拍到过类似的东西。那个帖主后来怎么样了？', time:'2026-01-20 10:20', floor:3 }, { user:'匿名_12ab', text:'@匿名_9e7c 照片我放了一张在回复里（帖主附了一张楼道照片，画面右下角确实有一个模糊的蹲坐黑影）。我放大看的时候，感觉那个黑影有头发。很长的那种。', time:'2026-01-20 12:40', isOP:true, floor:4 }, { user:'匿名_7b2a', text:'我有点在意你说"那个帖主后来停更了"。我记得他在停更之前的最后一句话是："我总觉得有人在我拍完照片之后，从取景框里看了我一眼。"——然后他再也没回复过任何人的私信。', time:'2026-01-20 13:00', floor:5 }, { user:'匿名_6h3f', text:'我也去过中南大厦，不过我是白天去的。白天那楼梯正常，13层就是13层。但我走到11层的时候，也看见墙上那行红字“别回头，也别数楼层”了——白天看也渗人。你们晚上去的，胆子是真大。', time:'2026-01-20 14:30', floor:6 }, { user:'匿名_9e7c', text:'楼主你说“那栋楼的所有楼层标牌，在竣工图上写的是本楼共12层”——那你那天晚上在楼梯间里数的13层，是不是你“多走”出来的那一层？你有没有留意过，11层和12层之间的拐角，比别的拐角窄了一点？', time:'2026-01-20 16:00', floor:7 }, { user:'匿名_5f6g', text:'这跟第二个进去的人那个帖子（“他已经来过了”）能对上。你们俩说的不是同一栋楼的同一层，是同一栋楼的不同“那一层”。建议你们俩别再约着去探了，那栋楼已经记住你们了。有些楼，去过一次就会被记名。', time:'2026-01-20 18:20', floor:8 } ] },

    { id:'p10', title:'我家自来水，每天晚上十点之后会变红', author:'匿名_9e7c', board:'求助解惑', views: 2764, image:'images/feature-darkred.jpg', content:'我在城南租了一个老小区的一居室，房租比同地段便宜了将近一半。搬进来那天是个晴天，可我一进厨房就闻到一股淡淡的、说不上来的腥味，我当时以为是下水道。房东把钥匙给我的时候，反复叮嘱我一句："晚上十点之后别开厨房的水龙头。"我没在意，以为只是水管老旧。\n\n我当时没多想，以为是水管老旧、噪音大之类的原因。入住第一周，我忘了这个提醒，十点过后去厨房接水，打开水龙头的那一刻——流出来的水是暗红色的，带着一股腥味，像稀释过的血。\n\n我吓到立刻把水龙头关掉。过了五分钟再打开，水流恢复正常。我安慰自己是水管生锈了。\n\n但接下来的一个星期，每天十点之后我都去测试——每一次都是同样的暗红色，同样的腥味。有一次我用透明玻璃杯接了一杯，放在灯下观察了十分钟，发现那些红色的物质在水中缓缓沉淀，沉到杯底之后，结成了一个非常微小的、类似凝血块的形状。\n\n我换了三个水龙头，都一样。我找了物业来看，物业查了管道说没问题，临走时用一种很复杂的表情看着我说："你是不是住302？"\n\n我说对。\n\n他说："那你别在厨房用水了，去卫生间洗吧。302……以前有个老太太在那里走掉的，听说是开煤气走的。走之前把水龙头全打开了，水留了一整夜。"\n\n我把那个杯子里的水倒掉了，但没来得及洗那个杯子。第二天早上起来，发现杯子里残留的那一点暗红色液体，变成了一个非常清晰的、用血迹写的"还"。', timestamp:'2026-01-21 22:18', comments:[ { user:'匿名_4f3a', text:'302……我好像在哪里见过这个房号。有个帖主说他租了一间房，每晚都能听到厨房有人在开水龙头——但那间也是302。你确定你租的是302？', time:'2026-01-21 23:05', floor:2 }, { user:'匿名_3a1b', text:'楼主建议你赶紧搬。有些东西不是"忘了走"，是"不想走"。你开了水龙头，相当于在跟她打招呼——她已经知道有人在那个空间里了。', time:'2026-01-21 23:40', floor:3 }, { user:'匿名_9e7c', text:'@匿名_3a1b 我今天白天试着在厨房放了一碗米。晚上回来的时候米少了大概三分之一。不是老鼠——碗周围没有脚印。我想搬，但租约还有五个月，押金三千。我今天还查了一下这栋楼的资料——302的前一个租客只住了两周就走了，押金都没要。我现在明白为什么了。', time:'2026-01-22 00:15', isOP:true, floor:4 }, { user:'匿名_4f3a', text:'302……我在旧房本里见过这个房号。老城区那片老小区，302正对着楼道的“冲角”，老人都说“冲角户不旺人”。上一个租客两周就走，可能不是第一个。楼主你查查这间房过去十年换过几任租客，都是住不长就走的。', time:'2026-01-22 01:10', floor:5 }, { user:'匿名_3a1b', text:'楼主你赶紧搬吧，别管押金了。那杯子里“还”字是水写的，水字说明她还“在那间屋子里”，不是走了。你放的那碗米少了三分之一——她在吃。你越试探，她越知道你在。三千押金跟命比，你自己掂量。', time:'2026-01-22 02:20', floor:6 }, { user:'匿名_8d7b', text:'你有没有注意到，每天十点之后除了水变红，还有没有别的异常？比如厨房的灯有没有自己暗一下、墙上的水渍有没有变多、或者半夜有没有听见“水龙头自己开”的声音？这些细节比水本身重要。', time:'2026-01-22 08:00', floor:7 }, { user:'匿名_5f6g', text:'我大半夜看到“用血迹写的还”已经睡不着了。这跟三院那个帖子里“底下埋着东西”的说法有点像——都是“水”。老城区那片地底下的水脉，是不是连着一个什么东西？楼主要是有条件，白天再回那间屋，把厨房的地漏也看看。', time:'2026-01-22 10:30', floor:8 } ] },

    { id:'p11', title:'连续一周梦见穿寿衣的老人在我床边数呼吸', author:'匿名_1f3e', board:'求助解惑', views: 3542, image:'images/feature1.jpg', content:'这件事是从上周二开始的。那晚我加班到很晚，回家倒头就睡，结果做了个梦——我躺在床上不能动，一个穿着深蓝色寿衣、脸上涂着白粉的老人站在我床边。窗外在下雨，雨声很密，但他的声音比雨声更清楚。我不确定那天发生过什么特别的事，但那晚我做了个梦——我躺在床上不能动，一个穿着深蓝色寿衣、脸上涂着白粉的老人站在我床边，伸出一只手，用食指一下一下点着空气，嘴里在数数："一、二、三……"\n\n他的声音很轻，但特别清晰。我醒来的时候，听到自己的呼吸正好卡在"三"和"四"之间。\n\n第二天晚上，同样的梦。同样的老人，同样的姿势，同样的数数。但他数的节奏变了——从"一、二、三"变成了"四、五、六……"似乎从我上次醒来时的地方继续下去。\n\n第三天晚上，他数到了"九"。第四天晚上，他数到了"十三"。我醒来的时间越来越晚——第一天是凌晨两点，第四天已经拖到了凌晨五点。\n\n第五天晚上我没敢睡太深。我设了闹钟，每隔一小时响一次。但每次闹钟响的时候，我都发现自己已经关掉了它——我完全不记得自己关过。而且在关掉闹钟的那个瞬间，我好像听到了那老人说了一个数字："十七。"\n\n第六天晚上，我决定不睡觉了。我泡了浓茶、刷手机、打开了所有的灯。到凌晨三点的时候，我实在太困了，靠着床头闭了一下眼睛。就那么一下——我听到一个很近很近的声音贴在我耳边说："别躲了。你还有七口。"\n\n第七天早上醒来，我第一个念头就是数自己的呼吸。我拼命地、重重地呼吸，像要把肺撑破一样。我不知道那个数字意味着什么。但今天早上照镜子的时候，我发现眼角的皱纹比上周多了一些，脸色灰白，像一个正在被什么东西从里面抽空的人。', timestamp:'2026-01-22 00:21', comments:[ { user:'匿名_7d2e', text:'这是民间说的"数息鬼"。据说如果你在梦里任由对方把你的呼吸数完，你就醒不过来了。解决方法是睡觉前在枕头下放一把剪刀，刀尖朝外，然后在床边倒扣一个碗。', time:'2026-01-22 01:00', floor:2 }, { user:'匿名_6h3f', text:'楼上的方法有用，但我听说更彻底的做法是：当晚在梦里主动问那个老人"你要数到多少"。如果你能问出口，梦就会醒。但前提是你得意识到自己在做梦——这需要练习。楼主你现在还能分得清自己醒着还是睡着吗？', time:'2026-01-22 01:45', floor:3 }, { user:'匿名_1f3e', text:'@匿名_6h3f 分不清了。我今天白天坐在办公室的时候，总觉得他站在我身后，继续在数。我现在只想知道一件事——如果那七口数完了，会发生什么？', time:'2026-01-22 02:30', isOP:true, floor:4 }, { user:'匿名_9b2c', text:'@匿名_1f3e 别等那七口数完。你现在就做一件事：在枕头底下放一把剪刀，然后在睡前用右手食指在自己额头上画一个圈。如果今晚他再来，你在梦里问他："你数的是谁的呼吸？"——如果他说"你的"，你就说"那你数错了"。这是我的方法，我试过。他后来没再来。', time:'2026-01-22 03:00', floor:5 }, { user:'匿名_7d2e', text:'“数息鬼”的记载我在老谱里见过：它数的是“你活着的时辰”，不是呼吸次数。你醒了它接着数，说明你已经“卡进它的节奏”里了。楼主，你数自己的呼吸时，有没有感觉每一次吸气都比上一次“短”一点？', time:'2026-01-22 04:00', floor:6 }, { user:'匿名_3d7f', text:'我也遇到过类似的，我当时是连着三天梦见有人在我床边数“四、五、六”，第三天醒来发现自己喉咙发紧。后来我照楼上的方法，枕头下放了把剪刀，那晚它没来。但我不敢确定是剪刀管用，还是它数完了。楼主你要么今晚就照做，要么就去医院，别硬扛。', time:'2026-01-22 09:00', floor:7 }, { user:'匿名_6h3f', text:'楼主你“分不清醒着还是睡着”，这已经是最危险的信号了。别等那七口数完，现在就做：剪刀放枕头下，刀尖朝外，床边倒扣一个碗。今晚要是还听到声音，你就在梦里问他“你数的是谁的呼吸”，他说“你的”你就说“你数错了”。我说的是认真的，别不当回事。', time:'2026-01-22 12:30', floor:8 }, { user:'匿名_9b2c', text:'楼主，你两天没回了，还醒着吗？你最后那句“如果那七口数完了，会发生什么”我看了心里发毛。你要是能看到这条，记住一件事：它数到几，你就“重数”——把已经数过的那一口，假装没数过。别让它数到头。', time:'2026-01-23 01:15', floor:9 } ] },

    { id:'p12', title:'楼下殡葬店橱窗里的纸人新娘，每天都在靠近我一寸', author:'匿名_3f1e', board:'巷中秘闻', views: 4230, image:'images/feature-paper.jpg', content:'我家楼下有一家殡葬用品店，开了很多年了。每天经过我都闻到一股纸灰和香烛混在一起的味道，天热的时候尤其重。橱窗里常年摆着一个穿红色嫁衣的纸人新娘，做工特别精细——五官画得很生动，嘴角微微上翘，像在笑。我从没多想，只是每天路过都会习惯性地看它一眼。店面很小，橱窗里常年摆着一个穿着红色嫁衣的纸人新娘，做工非常精细——五官用画笔描绘得很生动，嘴角微微上翘，像在笑。\n\n每天上下班我都会经过那家店。一开始没觉得有什么不对，就是普通的殡葬店摆设。但大概两周前，我注意到一个细节：那个纸人新娘的位置变了。原来她是在橱窗正中央的，现在她向左偏了一些——靠近橱窗玻璃的方向。\n\n我一开始以为是店主调整了摆放。但后来我每天经过都会注意一下——她每天都在朝玻璃方向移动。第一天偏了两厘米，第二天又偏了两厘米。到第五天的时候，她的脸几乎贴到了玻璃上，红色的嫁衣被玻璃压出了皱褶。她的笑好像在玻璃的另一面，正对着我。\n\n我有一天晚上下班晚了，大约十一点经过了那家店。殡葬店已经关门了，橱窗的灯还亮着。那个纸人新娘——她不是站在原来的位置了。她已经完全贴在了玻璃内侧，双手按在玻璃上，像在往外推。她的脸正对着街道，脸上画的微笑好像比白天大了几分。\n\n我跑回了家。第二天早上我特意提前出门，想再看一眼——殡葬店还没开门，但橱窗里空了。纸人新娘不见了。我以为终于结束了，松了一口气。\n\n然而当天晚上下班回来，我发现我家的门口放着一只红色的小鞋——纸扎的，大小不到我手掌的一半。鞋底上写着两个字："在等。"', timestamp:'2026-01-23 20:05', comments:[ { user:'匿名_8d7b', text:'纸人这种东西不能细看。特别是红纸扎的，画了五官的——那是"请回来"的。店主可能是进了不该进的东西，或者有人托了不该托的事。那只纸鞋你处理了吗？没处理的话今晚可能会在床边出现第二只。', time:'2026-01-23 20:50', floor:2 }, { user:'匿名_5f6g', text:'我以前住的地方也有一家殡葬店，那家店的纸人永远背对着街道。店主说"不能让它看到外面，看到外面就想出去"。你楼下的店主没有这个规矩，可能问题比想象中大。那些纸人，一旦被画上了眼睛，它们就能看见。一旦看见了，就想出来。', time:'2026-01-23 21:30', floor:3 }, { user:'匿名_3f1e', text:'@匿名_8d7b 我没敢碰那只纸鞋。今天下班回来它还在门口。我用手机拍了张照片，照片里鞋旁边多了一个红色的影子——我确定当时走廊里没有别人。我应该烧掉它吗？还是应该搬？', time:'2026-01-23 22:10', isOP:true, floor:4 }, { user:'匿名_9b2c', text:'@匿名_3f1e 如果你今晚必须回家，做三件事：一，进门的时候左脚先迈；二，把家里的扫帚倒立放在门口；三，如果今晚听到有人敲门，别问是谁，也别开门，对着门缝说一句"走错了"。如果门缝下面塞进来一张红纸，那你就搬家吧。越快越好。', time:'2026-01-23 22:50', floor:5 }, { user:'匿名_8d7b', text:'纸扎的东西“画了五官就能看见”，这个说法我信。我之前在老县志里看到过，旧时扎纸人有规矩：“扎人莫点睛，点睛要烧香”。店主给你楼下的纸人画了那么清楚的眼，还放橱窗里正对街，这是犯了忌讳的。', time:'2026-01-24 08:30', floor:6 }, { user:'匿名_4f3a', text:'这跟古董镜子那个帖子有点像——都是“家里出现不该出现的东西，还在‘在等’”。你那纸鞋上写的“在等”，跟“求不回来的姑娘”的说法是不是一路的？楼主你今晚要是回家，按楼上说的左脚先进门，扫帚倒立放门口。', time:'2026-01-24 11:00', floor:7 }, { user:'匿名_2f9d', text:'楼主，你拍的那张“鞋旁边有个红色影子”的照片还在吗？能描述一下那个影子的形状吗——是站着的人形，还是蹲着的？这很重要，能判断它是在“看”你还是“等”你。还有，你搬的话，那只鞋别带走，让它留在原地。', time:'2026-01-24 14:20', floor:8 } ] },

    { id:'p13', title:'我的影子活过来了，它摸了我一下', author:'匿名_4f3a', board:'灵异见闻', views: 3871, image:'images/feature2.jpg', content:'前几天我在公司加班到很晚，外面下着雨，空调嗡嗡地响，整层楼只剩我一个人。我走回工位的时候正好背对着灯，影子长长地拖在桌面上。我停下来揉了揉脖子，余光瞥了一眼桌面——影子还在。\n\n但它的手没动。\n\n我的手动了一下。影子没有动。我停住了。影子慢慢地把手抬了起来——做了一个我完全没有做的动作：它在摸我的后颈。一个冰凉的感觉从我脖子后面爬上来，像真的有一只手放在那里。\n\n我猛地回头。身后什么都没有。我再看桌面——影子已经恢复到正常的状态，随着我的动作同步运动了。我想说服自己是眼花了。但那天晚上回家，我站在玄关开灯的时候，发现我的影子比地面上的东西先到了。\n\n我往前走一步，影子往前走一步。我往左，影子往左。看起来一切正常。但我总觉得在光线的边缘处，影子的头部比我的头低了几厘米——像有人在低着头，弓着背，藏在那个黑色轮廓里面。\n\n第三天晚上，我半夜醒来，想去厨房倒水。房间里的夜灯亮着，我走过走廊的时候，脚下的影子忽然横着拉长——像有什么东西在影子内部翻了个身。我停住脚步，蹲下去，用手去碰影子——影子反过来握住了我的手。\n\n是冰的。而且影子握我的方向，和我的手伸下去的方向完全相反。我把手收回来的时候，影子的"手"没有收回去，依然停在那里，保持着抓住的姿势，留在了地面上。\n\n那晚之后，我开始害怕看到自己的影子了。我把自己藏在没有光的地方。但有时候我能感觉到身后有一个冰冷的东西，轻轻贴在我的后背——像一个人，用全身的重量，挤进了我的轮廓里。', timestamp:'2026-01-24 11:30', comments:[ { user:'匿名_9e7c', text:'这个是影子附体。民间说法是，影子是被光"压"住的第二个你。如果影子开始不跟你了，就说明有什么东西把你的影子当成了"门"。你越躲光，它就越容易从影子里爬出来。建议你白天站到太阳底下，用手摸自己的影子，说一句"这是我的"。如果影子在那一瞬间恢复了——就没大事。如果它依然不动——那就麻烦了。', time:'2026-01-24 12:40', floor:2 }, { user:'匿名_3a1b', text:'楼上的方法有用，但我听过另一个版本：如果影子已经碰过你了，就要用红墨水沿着影子的轮廓画一遍，把它"钉住"。不然它会慢慢学会走路。', time:'2026-01-24 13:15', floor:3 }, { user:'匿名_4f3a', text:'@匿名_9e7c 我试了。站在太阳底下，摸了自己的影子。它在那一瞬间恢复了。但我的手离开之后，它的手又慢慢抬了起来——比我的手高了半寸。我感觉它在学我。学得越来越像了。我今晚不想开灯了。', time:'2026-01-24 14:00', isOP:true, floor:4 }, { user:'匿名_8d7b', text:'@匿名_4f3a 你现在的情况比我预想的严重。如果你的影子已经学会独立动作，那就说明有什么东西已经占据了它。你现在要做的不是在太阳下摸它，而是——等到午夜12点整，站在一盏灯下，让影子完整地投射在地面上，然后你背对光源，用一支蘸了红墨水的毛笔，沿着影子的轮廓画一个完整的圈。画完之后，你离开那个圈，不要回头看，直接睡觉。如果明天白天你发现自己的影子比原来短了一截，那就是成功了一半。如果影子还在——你就只能去找懂行的人了。', time:'2026-01-24 15:00', floor:5 }, { user:'匿名_3a1b', text:'影子附体我见过一次，当时是我同事，他说“影子先到了”。我们按土办法，白天让他站太阳底下摸自己的影子说“这是我的”，结果那影子没跟着他的手走。后来是请了位懂行的，用红墨水沿影子轮廓画了个圈才压住。楼主你别拖，直接走最后那步。', time:'2026-01-24 16:20', floor:6 }, { user:'匿名_6h3f', text:'楼主你说“它的手比我的手高了半寸”——它是“学你”学过头了，还是它本来就不是你的影子？你白天在太阳底下试的时候，有没有注意它落在地上的方向跟你是不是反的？', time:'2026-01-24 19:00', floor:7 }, { user:'匿名_5f6g', text:'这跟“剪影子”那种说法是不是能对上？如果影子能被剪下来、能自己动，那它“学你”就是在“替换你”。楼主你今晚别关灯，最好拉个朋友陪着你，天亮前别让影子“独立”太久。', time:'2026-01-24 21:30', floor:8 }, { user:'匿名_9e7c', text:'我大半夜看到“它还在学我”已经起鸡皮疙瘩了。楼主你现在打字的手，是“你的手”吧？开个玩笑，但说真的——你今晚先把手机关了，别让屏幕的光照出影子，屏幕一暗，影子容易“出来”。', time:'2026-01-25 00:40', floor:9 } ] },

    { id:'p14', title:'族谱上我的名字后面，多了一个朱砂写的名字——那个人已经死了二十年', author:'匿名_7d2e', board:'民俗考据', views: 3156, image:'images/ritual-ink.jpg', content:'今年清明回老家祭祖，天一直阴着，路上下了两场雨。父亲让我去祠堂抄一份族谱备份，说今年轮到我们家。祠堂里又潮又暗，香火味浓得呛人。我翻到我们家那一页的时候，看到了我的名字："陆某某，生于1998年，次子。"后面跟着一个朱砂写的名字："陆某远，生于1978年，夭。"\n\n我愣住了。我从来没有听说过我有一个哥哥。我问父亲，父亲沉默了很久，然后说："你确实有一个哥哥，两岁就没了。你奶奶做主，把他从族谱上除了名。说是\'夭折的孩子不入谱\'，免得挡了后来人的路。"\n\n但族谱上有他的名字，用朱砂补写的。而且字迹非常新，像是最近一两年才加上去的。我仔细看那行字，发现"夭"字下面还有一行很小的字，用红笔写："当归。"\n\n我问父亲知不知道是谁加的。父亲没回答我，转头看着祠堂后墙的方向。当晚我一个人留在祠堂，想翻看更老的那一卷旧谱。旧谱放在一个红木箱子里，锁已经锈坏了。我打开箱子，翻到我们家那一页——旧的族谱上，"陆某远"的名字确实不在。但在那一页的背面，有一行用血写的、已经干涸发黑的字："为什么只有我死了？"\n\n那行字的笔迹和族谱上新添的那行字，完全一致。我在祠堂里待到了深夜。走的时候，我在香炉旁边看到了一个极小的东西——一颗已经发黑的、干掉的枣。', timestamp:'2026-01-25 16:20', comments:[ { user:'匿名_8d7b', text:'这种事在农村并不少见。夭折的孩子不入谱、不立碑、不留名——是为了不让"未成年的魂"牵住活着的人。但问题是，如果有人在后面补了名字，就说明那个孩子一直没有走。你看到的"当归"不是让他回来，是让他"回到该回的地方"——但你奶奶当年除名的时候，可能没有做"送"的仪式。', time:'2026-01-25 17:00', floor:2 }, { user:'匿名_9b2c', text:'楼主你那个"当归"旁边还有没有别的字？我在一些老谱里见过类似的情况——补名的人往往会写一句"归于某处"或"另立某位"，如果只写了"当归"，可能意味着那个魂还留在祠堂里。你晚上在祠堂有没有闻到烧纸钱的味道？如果是自己烧的那种混着潮气的味道，就说明有别的"人"也在守灵。', time:'2026-01-25 17:45', floor:3 }, { user:'匿名_7d2e', text:'@匿名_9b2c 你提醒了我。我从祠堂出来之后，身上确实有一股淡淡的烧纸味。我以为是在祠堂里沾上的——但回到家洗澡之后，那个味道还在。而且这几天我晚上睡觉的时候，总是听到一种很轻的、像小孩子在院子里跑的声音。我家住七楼，院子里没有小孩。我今天早上又看了一眼手机里拍的族谱照片——我发现"当归"两个字下面，还有一行极细极淡的笔迹，用朱砂写的："他回不来了。你来替他。"', time:'2026-01-25 18:30', isOP:true, floor:4 }, { user:'匿名_3a1b', text:'@匿名_7d2e 那句话的意思是：他想要你替他活着，或者说，他想通过你重新"活"一次。你父亲没告诉你的那一部分，可能比你想的更多。建议你下次回祠堂的时候，带一把新香，点三根插在香炉里，然后跪下来，对着那本族谱说一句话："你是我的哥哥，我认你。但你该走了。"——说完磕三个头，起身就走，不要回头。这是我能想到的最体面的送法。', time:'2026-01-25 20:00', floor:5 }, { user:'匿名_9b2c', text:'“夭折的孩子不入谱、不立碑”，是为了不让他们“牵住”活着的人。但你奶奶当年除名的时候没做“送”的仪式，他（你哥）就一直没走。那行“他回不来了，你来替他”，是他在跟你商量——你千万别应。', time:'2026-01-26 00:20', floor:6 }, { user:'匿名_8d7b', text:'楼主你回祠堂那次，有没有注意到香炉里的灰是不是“刚烧过的”？你奶奶当年要是做过“送”，会留一点香灰压在某块砖下面。你要是能找到那块砖，把香灰捧一捧撒回祠堂门口，说不定能帮上忙。', time:'2026-01-26 09:10', floor:7 }, { user:'匿名_5f6g', text:'楼主，你住七楼却听见“院子里小孩在跑”——那不是院子里的，是“他”在熟悉你的家。你按楼上说的，下次回祠堂带三根新香，跪下说“你是我的哥哥，我认你，但你该走了”，磕三个头起身就走，别回头。这话说出来，既是认他，也是送他。', time:'2026-01-26 14:00', floor:8 } ] },

    { id:'p15', title:'老城区停车场手印后续——我查到了一点东西', author:'匿名_3f1e', board:'巷中秘闻', views: 4892, image:'images/post-parking-v2.jpg', content:'我是之前发《老城区地下停车场手印》的那个人。今天更新一个后续——因为我实在睡不着了。\n\n上次帖子发完之后，我收到了一个私信，对方说："你看到的手印不是\'很多人的手\'，是\'同一个人反复按了很多次\'。下次你再去停车场，带一支香，放在电梯井门口，别点燃，竖着靠墙放着。"\n\n我起初觉得这个说法太玄了，但还是照做了。前天下午，我趁着人少又去了一次地下三层。我按他的说法，在废弃电梯井门口靠墙竖了一支香，然后用手机拍了几张照片，回来之后仔细放大看——墙上的手印，确实不是一群人的。把所有手印放在一起比大小、比指节间距，得出的结论是：全部属于同一个人。\n\n我更仔细地看了其中几个最清晰的手印，在掌根的位置发现了一条极细的横纹，像是某种特定的纹路——不是天然的掌纹，更像是有图案的印章压出来的。我拍了下来，然后回家把它和在别处拍到的老城区地图叠加在一起比对，发现那条横纹的走向，正好对应着老城区某条已经被填平的路。\n\n那条路以前叫什么名字，我不确定。但我在查资料的时候，看到了一个名词："墟门"——这个位置附近，在旧地图上标着一个很小的叉，旁边写着"不在此处开门"。\n\n看到"不在此处开门"那行小字的时候，我后颈的汗毛全竖起来了。我想起上回帖子里有个坛友说，梧桐巷西段的路面上也有一道像手形的裂缝。如果"墟门"不是一扇门，而是绕着老城区一圈的"环"……那停车场这面墙上的手印，就不是"敲门"，是有人在门里面，一遍一遍地确认：门，到底关没关上。我决定明天就把那支香收回来，不再放了。有些确认，确认到最后，就是回答。', timestamp:'2026-01-27 19:00', comments:[ { user:'匿名_7d2e', text:'"墟门"……我在一份旧手抄本里见过这个词。上面写着："凡遇门，勿久立；凡遇手印，勿覆掌。"你放的那支香，如果还没倒，说明它还在等。如果它倒了，说明门已经开了。', time:'2026-01-27 20:15', floor:2 }, { user:'匿名_9e7c', text:'我有个朋友之前也去过那个停车场，他说他看到的手印有些是朝上的——像有人在用指尖从墙里面往外刮。我不知道该不该信这个，但他从此再也没进过那个停车场。', time:'2026-01-27 21:00', floor:3 }, { user:'匿名_3f1e', text:'今天下午我又去了一趟停车场。那支香还在那里，没有倒。但它的影子落在地面上的方向是反的——不朝向光源，而是朝向电梯井。我不知道这说明什么，我决定把这支香留在那里，不再动了。有些门如果正在被敲，你最好别靠近。', time:'2026-01-27 22:30', isOP:true, floor:4 }, { user:'匿名_4f3a', text:'@匿名_3f1e 等等，你说的那条被填平的路……是不是梧桐巷往西延伸的那一段？我前几周经过那边的时候，看到路边的水泥地面上有一道裂缝，裂缝的形状像一只手。我没敢多看就走了。但今晚看到你这个帖子，我想起来了——那道裂缝的走向和你说的横纹好像一样。如果你说的"墟门"是真的，那它可能不止一处。', time:'2026-01-27 23:10', floor:5 }, { user:'匿名_7d2e', text:'“墟门”这个词我在旧手抄本里见过不止一次，后面常跟着一句“凡遇门，勿久立；凡遇手印，勿覆掌”。楼主你查到的“不在此处开门”，那才是关键——说明那片地方官方知道，但故意没标。你最好把那行字记牢，别再往那儿放香了。', time:'2026-01-28 00:30', floor:6 }, { user:'匿名_9e7c', text:'你说那条横纹对应一条被填平的路。你能确定那条路现在地面上还有没有“痕迹”吗？比如井盖、地砖的颜色、或者一到下雨天就先积水的那一段？这些是“路还在下面”的记号。', time:'2026-01-28 08:40', floor:7 }, { user:'匿名_3a1b', text:'我也遇到过类似的地面裂缝，在城西旧货市场后面，形状像个摊开的手掌。当时我拍下来了，跟楼主你说的“掌根横纹”一对比，走向确实像。要是真连成环，那老城区地底下“那扇门”怕是不止一处，是一整圈。', time:'2026-01-28 13:20', floor:8 }, { user:'匿名_8d7b', text:'楼主，那支香你别再动了，也别再回去看了。香影子反着、手印全是同一个人的——说明“门那边”的东西一直在等你确认“它开着”。你现在最该做的，是把这篇帖子里的坐标全抹了。有些线索，查到“它是入口”这一步就够了，再往下就是送人头。', time:'2026-01-28 19:00', floor:9 } ] },

    { id:'p16', title:'（补档）关于古董镜子的帖主……有人能联系上他吗', author:'匿名_3a1b', board:'求助解惑', views: 2430, image:'images/feature3.jpg', content:'我发这个帖子，是因为实在有点睡不着了。之前发《古董镜子》那个帖子的帖主"匿名_7b2a"，从1月23号之后就没再上线了。他的最后一条回复是："铁盒又露出来了，我把它埋深了一点。"\n\n我翻了翻他的发帖记录，发现他在断更前一天还在别的帖子下面留了一句言："我今天早上照了一下卫生间的镜子，发现镜子里我的脸旁边多了一张脸。看不清楚是谁，但她在对我笑。"\n\n之后他就没再出现过。\n\n有没有人能联系上他？他之前说过自己住在老城区哪个小区来着？我记得他说过"槐树底下的土是松的"……如果有人认识他住哪，麻烦私信我。我有点担心。', timestamp:'2026-01-30 14:00', comments:[ { user:'匿名_9b2c', text:'我也注意到他断更了。他最后一次登录是1月24号凌晨，之后再也没有已读消息的标记。我私信了他三条，都是未读状态。', time:'2026-01-30 15:20', floor:2 }, { user:'匿名_5f6g', text:'我记得他提到过"小区花园的老槐树"。老城区那边带槐树的小区不多，我查了一下，梧桐巷那片有旧家属院，门口有一棵很老的大槐树。如果有人在那附近住，可以去看看那棵树底下有没有翻开过的痕迹。但要注意——如果树根旁边有人形的凹陷，就别靠近了。', time:'2026-01-30 16:00', floor:3 }, { user:'匿名_8d7b', text:'我有一种不好的预感。那个帖主最后一次回复说的"铁盒又露出来了"，说明那面镜子的碎片一直在尝试回到地面。如果那东西是某种"有入口的器具"，它可能已经……换了一个容器了。比如，一面还在用的镜子。帖主最后提到"她在对我笑"——如果那个"她"已经从镜子里出来了，那"她"可能就在帖主的家里。帖主不更新，不是因为不想更新。', time:'2026-01-30 17:30', floor:4 }, { user:'匿名_3a1b', text:'我刚才试着给"匿名_7b2a"发了一条私信，显示"已读"了。但对面没有回复。我不知道是帖主本人看到的，还是别的什么看到的。', time:'2026-01-30 19:00', isOP:true, floor:5 }, { user:'匿名_7d2e', text:'“有入口的器具”这个说法我信，老谱里管这叫“活器”——会自己找“新主人”的东西。古董镜子要是真成了活器，它从碎片里“换了个容器”，可能就在找一面还在用的镜子。楼主你们谁最近新买了镜子或搬了新家，留意下有没有“不是自己的倒影”。', time:'2026-01-30 21:00', floor:6 }, { user:'匿名_9b2c', text:'我私信过帖主，显示已读，但他没回。我在想，如果“已读”是别的什么看的，那它读完会不会来找我？楼主你发这个寻人帖之前，有没有收到过什么“奇怪的已读”？就是那种你根本没给人发过消息，却提示已读的。', time:'2026-01-31 02:10', floor:7 }, { user:'匿名_8d7b', text:'帖主断更到今天已经一周多了。老槐树底下要是真埋了铁盒，去看一眼树根旁边有没有翻开过的痕迹——但记住，如果看到树根旁边有人形的凹陷，别靠近，直接走，别回头。有人认识那小区的话，替大家去看看，报个平安。', time:'2026-01-31 10:30', floor:8 } ] },

    { id:'p17', title:'我也去了中南大厦，我见到了那个"不存在的人"', author:'匿名_6h3f', board:'灵异见闻', views: 3214, image:'images/cell-bg.jpg', content:'看了"匿名_12ab"那个中南大厦的帖子之后，我一开始是不信的。但上个星期六晚上，雨刚停，空气里全是土腥味，我一个人鬼使神差地到了那栋楼下。我是那种越是听说邪乎越想去看看的人，犹豫了十分钟，还是进去了。但我是那种越是听说邪乎越想去看看的人。上周六晚上我一个人去了。\n\n我是从侧门进去的，没有走正门。从一楼走到七楼，一切正常。走到十楼的时候，楼梯间墙上出现了红油漆字——不是"别回头"，是另一句话："他已经来过了。"\n\n我当时愣住了。那个"他"指的是谁？我继续往上走，走到十一楼和十二楼之间的拐角处——楼梯正中央坐着一个穿灰色外套的男人。他低着头，头发很长，看不清脸。我没敢问话，侧身从他身边挤过去了。\n\n我到了十二楼之后没再往上走。我原路返回，走到十楼的时候发现那个男人不在楼梯上了。我下到一楼出了侧门，掏出手机准备看时间——锁屏屏幕上有一条未读通知。打开之后是一条短信，发自"未知号码"，内容只有一行字："你刚才从我旁边经过的时候，我在看你。"\n\n我回头看了一眼侧门。门是锁着的——锁链从外面挂着的，我进去的时候是从门缝里钻的。那扇门从外面锁死了。我不可能从那里出来。\n\n但我确实出来了。我不知道我是怎么出来的。', timestamp:'2026-02-02 01:20', comments:[ { user:'匿名_12ab', text:'等等……你描述的灰外套男人，我在那天晚上的照片里也看到过。我当时没当回事，以为是别的探险者。但你刚才说他在十一楼到十二楼的拐角坐着……我那一整夜都在11层到13层之间循环，从来没有在拐角见过任何人。但他可能在你看得到的地方坐着——而我经过的时候，他不在那里。因为我们经过的是不同的"那一层"。', time:'2026-02-02 02:00', floor:2 }, { user:'匿名_5f6g', text:'我有个问题——那条短信还在你手机上吗？你试着点开那个"未知号码"，看看能不能回拨。如果能通，接电话的人可能是中南大厦里某一个"还在值班"的人。如果回拨之后是空号……那你收到的这条短信，可能是从信号覆盖不到的地方发出来的。', time:'2026-02-02 03:10', floor:3 }, { user:'匿名_6h3f', text:'@匿名_5f6g 我试了，回拨过去是"您拨打的号码不在服务区"。但我去看了一下通话记录——这个号码在我手机里显示的名称是"中南大厦值班室"。我从来没有存过这个号码。而且这栋楼已经废弃十年了，怎么会有值班室？我现在有点后悔进去了。', time:'2026-02-02 04:00', isOP:true, floor:4 }, { user:'匿名_12ab', text:'你说的“灰外套男人”，我翻了我那晚的照片，确实有一张角落里有个模糊的影子，我一直以为是别的探险者。但你说是从外面锁死的门——那我那晚看到的“他”，可能就是你说的“不存在的人”。我们俩去的不是同一层，但看到的是同一个东西。', time:'2026-02-02 05:00', floor:5 }, { user:'匿名_5f6g', text:'楼主，你收到那条短信的时候，手机还剩多少电？还有，你出侧门之后，有没有回头看那扇门上的锁——锁链是从外面挂的，但你出来时它是“锁着”的，那你是怎么从里面推开一扇外锁的门出来的？这个你细想过没有？', time:'2026-02-02 09:20', floor:6 }, { user:'匿名_9e7c', text:'我也在夜里去过一次中南大厦附近，没进去，就在外围。我在墙根蹲了半小时，听见楼里有“哒、哒、哒”的脚步声，节奏特别稳，像有人在楼上值班巡逻。可那楼废弃十年了，谁在值？', time:'2026-02-02 14:40', floor:7 }, { user:'匿名_3a1b', text:'楼主，你回拨那个“中南大厦值班室”的号码，占线三次之后会变成“不在服务区”，对吧？那就别打第四次了。值班室的电话响了，接起来的不一定是人。这楼你最好一次都别再去了，去过的，都会被记名。', time:'2026-02-02 20:10', floor:8 } ] },

    { id:'p18', title:'19年三院那个帖子又被顶起来了……有人知道那是什么地方吗', author:'匿名_8d7b', board:'求助解惑', views: 5147, image:'images/signal-geo.jpg', content:'今天下午雨下得很大，我窝在沙发上刷论坛，看到有人考古，把去年那个"19年三院"的帖子顶上来了。我点进去看了一下，越看越觉得不对劲——那帖子像被一只看不见的手，从去年一路翻到了今年。我点进去看了一下，原帖主说路过老第三医院心口发闷、脑子里闪白影子、想不起来发生过啥。下面回复不多，但有一个人说了一句："别问了，问就是集体癔症。"\n\n但我发现那个帖子里有一条被折叠的回复，点开之后写着："我在那家医院做过护工。那个夏天确实死了很多人，但官方的死亡名单上没有他们的名字。他们被登记在另一份名单上——那份名单的标题叫《认知污染损失人员登记表》。那家医院的后面有一片空地，草长得特别高，底下埋着很多没有名字的小木牌。"\n\n那条回复的发布者是"匿名_9b2c"。我查了一下他的其他回复，发现他还在"族谱"帖和"自来水变红"帖下面留过言。这个人的身份好像不简单。\n\n有谁知道三院到底发生过什么吗？', timestamp:'2026-02-10 22:00', comments:[ { user:'匿名_7d2e', text:'"认知污染损失人员登记表"……我在档案室里见过类似的表格。不是医院的文件，是总局的表格格式。如果你说的三院确实有这种东西，那它可能不是一家普通的医院——它是总局在地方设的"前哨站"之一。那些没名字的小木牌，可能就是……没有"活着出来"的人。', time:'2026-02-10 23:15', floor:2 }, { user:'匿名_4f3a', text:'我住的地方离三院不远。我小时候听老人说过，"三院后面那块地种不出庄稼，连草都不长，只有一种白色的花，每年夏天开，开过就谢，谢了之后地面会渗出水"。他们说那地方底下有东西。具体是什么，没人说清楚。', time:'2026-02-11 00:30', floor:3 }, { user:'匿名_3a1b', text:'@匿名_8d7b 我建议你别深挖了。有些地方的名字出现在官方地图上，是因为他们希望你知道它存在——但不能知道它为什么存在。你查得越深，可能会有越多人注意到你在查。而那些人，不一定都是坛友。', time:'2026-02-11 01:00', floor:4 }, { user:'匿名_9b2c', text:'既然被点名了，我说几句。我在三院做过一段时间的"特殊护工"。那个夏天确实不太平，但真相不在官方文件里。那些没名字的木牌——上面写的不是人名，是编号。格式是"年份-地点-序列号"。我见过一块木牌上写着"2019-LC-037"，后来我查了一下，同年同月，老城区发生了一起"不明原因集体昏厥事件"，官方通报是"食物中毒"。三院那年的死亡人数比通报的多。至于多的那些人去了哪里——我不确定。但我知道那块木牌后来不见了。', time:'2026-02-11 02:00', floor:5 }, { user:'匿名_3a1b', text:'“认知污染损失人员登记表”——这个名目我在旧档案室见过类似的格式，但都只有编号没有正文。楼主你说“总局的表格格式”，那这个“前哨站”的说法，我倾向于是真的。三院那片地，我建议你们谁也别再去探了。', time:'2026-02-11 03:10', floor:6 }, { user:'匿名_7d2e', text:'我也遇到过类似的地方，在城西一片废弃厂区，里面也是“小木牌”，但没有名字，只刻编号。我当时没敢数有几块。楼主你提到“2019-LC-037”这个编号，跟我见过的格式一模一样——年份-地点-序列号。这不是巧合。', time:'2026-02-11 09:00', floor:7 }, { user:'匿名_4f3a', text:'楼主，你说三院后面那块地“夏天开一种白色的花”——那种花你见过实物吗？我听说那种花是“底下埋了东西”才会开，花谢之后地面会渗水。你能描述一下那花的形状吗？叶子是圆的还是针形的？', time:'2026-02-11 12:40', floor:8 }, { user:'匿名_5f6g', text:'我大半夜看到“死亡名单上没有他们的名字”这句已经后背发凉了。楼主，你说得对，别深挖了。有些名字出现在地图上，是因为有人希望你看见它存在、又不希望你搞清它为什么存在。你查得越深，注意你的人越多——而那些人，不一定都是坛友。', time:'2026-02-11 18:20', floor:9 } ] },

    { id:'p19', title:'【置顶】关于最近论坛出现的"关联线索"情况的说明', author:'系统管理员', board:'公告', views: 9999, content:'近期论坛内出现多篇涉及"特定地点""特定编号""特定机构"的帖子，已触发系统关键词筛选机制。为保持论坛正常运转，现做如下说明：\n\n1. 本论坛为匿名灵异讨论社区，所有内容均为用户个人经历分享，不代表本论坛立场；\n2. 请勿在帖子中发布具体地址、真实姓名、个人联系方式；\n3. 若发现帖子内容存在"诱导性操作"（如"去某地""做某事"），管理员有权进行删除处理；\n4. 关于"三院""墟门"等关键词的讨论，请各位坛友注意尺度。\n\n另外，有用户反馈近期私信收到"邀请"类信息，请注意甄别。本论坛不会通过私信方式向任何用户发送"线下见面""物品传送"等请求。如收到类似消息，请截图保存并私信管理员。\n\n祝各位坛友平安。', timestamp:'2026-02-12 09:00', comments:[ { user:'匿名_9e7c', text:'管理员出来说话了。有意思的是——这个公告本身就是在暗示"那些帖子里的东西是真的"。如果真的是普通灵异故事，管理员不会特意出来强调"不要去做"。', time:'2026-02-12 10:30', floor:2 }, { user:'匿名_5f6g', text:'我注意到公告里有一条很微妙的话："本论坛不会通过私信方式向任何用户发送\'线下见面\'\'物品传送\'等请求。"——这意味着确实有人收到了。而且不是普通坛友互发的那种，是带有特定目的地指向的那种。那些收到私信的人……是不是都在某些特定帖子里留过言？比如"停车场"或者"中南大厦"？', time:'2026-02-12 11:20', floor:3 }, { user:'匿名_3f1e', text:'我现在有点后悔发停车场那个帖子了。那之后私信我的人差不多有十几个，其中有三四个人说的内容一模一样："你确定你放香的时候没有回头看电梯井？"我确定我没有。但他们轮番来问，好像是在确认什么。我回复了其中一个人说"没有回头"，他回了我一句："那你运气好。"然后就再也没发过消息了。我现在在想——"运气好"是什么意思？', time:'2026-02-12 12:00', floor:4 }, { user:'匿名_7b2a', text:'（此用户显示为"已注销"）', time:'2026-02-12 13:00', floor:5 }, { user:'匿名_3a1b', text:'等等……"匿名_7b2a"刚才显示上线了？我一直在关注他那个断更帖，他的账号状态之前一直是"离线"，头像也是灰的。但刚才系统显示他"在线"了大概三秒钟。我立刻给他发了一条私信，显示"已读"了。但他没有回复。然后他账号就变成了"已注销"。是帖主本人注销了账号……还是别的什么，用他的账号点了一下"已读"？', time:'2026-02-12 14:00', floor:6 }, { user:'匿名_9b2c', text:'管理员，你说“不会通过私信发送线下见面或物品传送的请求”——那如果收到了这种私信，除了截图私信管理员，还有别的处理办法吗？比如那个发信人，能查出来是什么来头吗？我最近收到一条，落款是“守夜人”，我没敢点开。', time:'2026-02-12 15:20', floor:7 }, { user:'匿名_7d2e', text:'公告里点名的“三院”“墟门”，跟停车场、中南大厦那几篇帖子是不是都在老城区那条线上？你们有没有发现，所有出事的帖子，坐标好像都绕着同一条被填平的路转。这条公告发出来，等于是官方替我们确认了：那些帖子里的东西，是真的。', time:'2026-02-12 17:00', floor:8 }, { user:'匿名_3f1e', text:'我大半夜看完公告已经睡不着了。“运气好”是什么意思，我到现在没想明白。管理员你要是有权限，帮我们看看发那种私信的人是不是同一个IP——要是同一个，那他们轮着来问同一个问题，就是在“对答案”，不是关心。', time:'2026-02-12 20:30', floor:9 } ] },

    { id:'p20', title:'夜路三不借：伞、火、盐——老人传下来的规矩', author:'匿名_5b4c', board:'民俗考据', views: 2268, image:'images/ritual-ink.jpg', content:'回老家看外婆，她正坐在院子里用红绳编东西。我随口问她，下雨天要是路上有人向你借伞，该不该借。\n\n外婆手上没停，慢悠悠说：“借，可以借，但你得先看他‘借的是伞，还是借你挡雨的那个檐角’。伞借出去还能回来，檐角借出去，就回不来了。”\n\n她又说，夜里路上有三样东西不能随便借：\n1. 伞——借走的是你遮住的那片“檐”。\n2. 火——借走的是你还“亮着”的那口气。\n3. 盐——借走的是你“留得住人”的那份味。\n\n“要是半夜真有人跟你借这三样，你就把东西放在地上，退三步，让他自己拿。拿完你转身就走，别回头，也别说‘不用还’。”\n\n我问为什么。外婆把编好的红绳系在我手腕上，说了句：“因为说‘不用还’的，都是急着想留点东西在你身边的。”', timestamp:'2026-02-14 15:30', comments:[ { user:'匿名_2f9d', text:'这个说法我奶奶也讲过。她说夜里借伞的，十有八九不是人——因为正经人不会在那种天气里一个人站在路边等你。', time:'2026-02-14 17:00', floor:2 }, { user:'匿名_6h3f', text:'“放地上让他自己拿，退三步”——这是规矩，也是底线。你把东西放下，就是告诉他“东西我给了，但我不欠你情”。别开口，一开口就扯上因果了。', time:'2026-02-14 19:20', floor:3 }, { user:'匿名_5b4c', text:'外婆还叮嘱我，说我们这片老城区，下雨天路灯下面站着等“借东西”的，比别处多。她还说，家里那把黑布伞，是“镇宅用的”，平时不许我拿去用，只下雨天自己撑。我今天才明白她什么意思。', time:'2026-02-14 22:00', isOP:true, floor:4 }, { user:'匿名_3a1b', text:'“家里那把黑布伞镇宅”——这个我熟。老城区好些人家都有这么一把，雨天自己撑，晴天收在门后。那是“挡檐角”的东西，借不得，也换不得。楼主你外婆家那把，千万别动。', time:'2026-02-15 08:30', floor:5 } ] },

    { id:'p21', title:'连续三晚，有人用伞骨在窗外敲我的窗', author:'匿名_c2a9', board:'求助解惑', views: 1987, image:'images/feature1.jpg', content:'我租的老小区，三楼，窗户朝北，对着一条没什么人走的巷子。\n\n第一晚，凌晨一点半，我还没睡，听见窗外有节奏地响——“嗒、嗒、嗒”。不是雨点，是硬物敲玻璃，一下一下，不快不慢，三下为一组，中间隔很久。我以为是楼上掉东西，没理。\n\n第二晚，同样时间，同样节奏。这次我掀开窗帘一角看了一眼——窗外没有人。巷子里路灯亮着，水泥地上干干净净。但我看见窗台外侧，放着一把旧伞，伞骨朝上，伞尖正对着我的玻璃。\n\n我吓得没敢再睡。天亮后我把那伞扔到了楼下垃圾桶。\n\n第三晚，凌晨一点半，声音又来了。我壮着胆子贴着门缝问了一句“谁”。声音停了。然后我听见楼下，那把被扔掉的伞，在垃圾桶里轻轻撑开的声音。\n\n我连夜把门反锁，把家里那把黑布伞撑开，立在窗台上。之后那声音就再没出现过。但我总觉得，它还在巷子尽头站着，等我哪天把伞收起来。', timestamp:'2026-02-16 00:45', comments:[ { user:'匿名_7d2e', text:'伞骨敲窗，三下为一组——这是“请人开门”的暗号。老话讲“敲三不敲四，敲四是送信”。它想让你开门，或者让你应一声。楼主你应了那声“谁”，就已经被它记住了。', time:'2026-02-16 02:00', floor:2 }, { user:'匿名_5b4c', text:'楼上的说法对了一半。三下是“请开门”，但你这窗户朝北、对巷子——那是“借檐角”的老位置。你放了把黑布伞在窗台，等于告诉它“这户有檐，不进”。这招是老人教的，管用，但撑开的伞记得天亮前收回来，不能一直立着。', time:'2026-02-16 03:10', floor:3 }, { user:'匿名_c2a9', text:'@匿名_5b4c 我一直没敢收，伞在窗台立了三天了。今天早上起来发现伞面上落了一层灰，是那种灰白色、像烧过纸的灰。我家窗台朝北，不可能落这种灰。我现在不知道该不该把它收起来。', time:'2026-02-16 10:00', isOP:true, floor:4 }, { user:'匿名_3a1b', text:'楼主，那把伞上落了“纸灰”——说明它不只是想借檐，是想留东西。听我一句：今天白天，太阳最好的时候，把伞收下来，抖三抖，对着太阳晒一个小时，再收进屋里。晚上别再立窗台了。要是今晚那声音还来，你就把窗打开一条缝，对巷子说一句“檐不给，人也走了”——然后关窗，无论听到什么都不回头。', time:'2026-02-16 12:20', floor:5 }, { user:'匿名_6h3f', text:'我也住老城区，之前半夜也听过敲窗声，后来发现是对面楼顶有只猫。但楼主你这情况不一样——伞都放上窗台了，这是“对象明确”的。按楼上说的，白天晒伞，晚上别立。还有，你这几天留意下：巷子里路灯下，是不是多了一个“撑伞站着”的人？', time:'2026-02-16 15:40', floor:6 } ] },

    { id:'p22', title:'在旧纸厂废墟捡到一枚木牌，上面只有编号', author:'匿名_0c4e', board:'灵异见闻', views: 2710, image:'images/cell-bg.jpg', content:'上周末跟几个朋友去旧纸厂那片废墟“探险”，就是老城区边上那片，厂区早就搬空了，只剩下几间塌了半边的厂房。\n\n我们在厂房后面一块翻起的土里，捡到一枚巴掌大的木牌。木头很旧，边角都磨圆了，上面只刻着一行字：“2019-LC-037”。\n\n我以为是工地上的老标牌，没当回事，顺手揣兜里带回了家。\n\n当天晚上，我发现我家客厅的影子不太对——我开灯走过去，我的影子跟着我，但落地灯那盏灯投出来的第二道影子，停在原地，没动。\n\n我安慰自己是灯光。可第二天晚上，那道“多出来的影子”出现在我卧室墙上，还比昨天大了一圈。\n\n第三天，我把那木牌翻出来细看，发现背面还有一行更小的字，像是后来才刻上去的：“已取回。勿再埋。”\n\n我上网查“2019-LC-037”，什么也查不到。但我翻论坛的时候，看到有个帖子里说，三院那片空地上埋着“没有名字的小木牌”，格式就是“年份-地点-序列号”。\n\n我现在不知道该把这木牌埋回去，还是留着。但我今天早上发现，那木牌上“2019-LC-037”的“7”，好像变成了“8”。', timestamp:'2026-02-18 21:30', comments:[ { user:'匿名_9b2c', text:'楼主，把木牌放回原处，现在、立刻。你查的“三院木牌”是我在另一个帖里提过的——那种编号不是工号，是“登记号”。2019-LC-037，LC 是某个分区代号，037 是当年那批“登记”里的第三十七个。它背后那行“已取回，勿再埋”，说明它本来有人管。你把它带回家，等于从登记簿上“借”走了一个。', time:'2026-02-18 22:40', floor:2 }, { user:'匿名_3a1b', text:'楼主你说的“多出来的影子”，跟之前那个“影子活了”的帖子有点像，但你这个更危险——你是把“登记物”带回了家。它在你家“长大了”，说明它在熟悉你。今天就把木牌放回原处，放的时候背过身，放完直接走，别回头。要是今晚影子还在，就别关灯睡。', time:'2026-02-18 23:50', floor:3 }, { user:'匿名_0c4e', text:'@匿名_9b2c 我下午去放回去了，放在原来那块翻起的土里，还压了块砖。但回来之后我总觉得不对——我放回去的时候，发现土里好像又多了几枚木牌，跟我那枚一样的格式。我没敢数，放完就跑了。', time:'2026-02-19 08:10', isOP:true, floor:4 }, { user:'匿名_5f6g', text:'“又多了几枚”——楼主你快走吧，那片废墟以后别去了。旧纸厂那块地，早几年就是“处理过”的，后来风声紧了才没人管。那几枚新木牌不是“新登记的”，是“新取回的”。你放回去那一枚，等于把名单还了回去，可它们已经知道你认得路了。', time:'2026-02-19 10:30', floor:5 }, { user:'匿名_7d2e', text:'楼主，你那枚木牌背面“已取回，勿再埋”——你细想过没有，这句话是给谁看的？是给捡到的人看的，还是给“埋进去的人”看的？如果是后者，那你把它带回家又放回去，中间这一趟，够“它”认路了。这周晚上睡觉，门口撒把盐。', time:'2026-02-19 13:20', floor:6 } ] }
];



