        story: '【事件记录 · 夜巡护城河】记录员：外勤三处·见习观察员。某夜巡夜组持溺声铃沿老城区护城河例行巡查。行至旧码头附近，铃舌自行震动，发出三声低鸣——一声比一声近。领队示意熄灯伏身。铃鸣停时，水面浮起一层极薄的雾，雾中隐约传来一句很轻的话，用的是几乎失传的老城区口音：“你们踩到我的门槛了。”众人屏息不动，直到雾散。次日回队登记，领队在备注栏只写了四个字：“未敢应答。”'

