        story: '【民间口述 · 梧巷旧宅】收缴后我们做了试点。烛焰平稳，径直指向旧宅后墙——墙外是三十年前被填平的旧河道，早已没有路。老住户看了说：“你们要是顺着它走，今晚就走到水里去了。”后来查明，那面墙的地基下压着一块旧界石，界石背面刻着一个“归”字。烛指的从来不是“家的方向”，是“该回的地方”。'

